contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address _baseToken,
        address _baseToken2,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public payable {
        require(_feeRate <= 5_000, "fee rate precondition");
        require(_baseToken != _baseToken2, "distinct base tokens");

        c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        );

        address firstBaseToken = c.baseToken();
        bool firstInitialized = c.initialized();

        bool reverted;
        try c.initialize(
            _baseToken2,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address afterBaseToken = c.baseToken();
        bool afterInitialized = c.initialized();

        assert(firstInitialized && reverted && afterBaseToken == firstBaseToken && afterInitialized);
    }

    receive() external payable {}
}

